      SUBROUTINE BFGETCC     GET PARAMETERS DESCRIBING THE FRINGE FIELD OF A BENDING MAGNETCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM26A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'NXRAN.CIN'      INCLUDE 'XRAN.CIN'      INCLUDE 'XRAN4.CIN'CC     LOCAL VARIABLESC      INTEGER  IADR, IAPB, ILAYL, IRAB, J, NXR      REAL  DATAR      EXTERNAL DATARCC------------------------------------------------------------------C     POLE-FACE ROTATION ANGLEC      NHGAP = 2      NFINT = 3      IADR = I + 1      BE = DATAR(IADR)      IF (PRAN2(1) .NE. 0.0) BE = BE + PRAN2(1)*XRAN(1)      BE = BE*UNITI(7)CC     RANDOM ERRORS AND AUTOMATIC SETTING OF POLE-FACE ROTATION ANGLEC      IF (NORD1 .LT. 1) GO TO 240      IF (BEFORE) THEN        IF (RANZC) THEN          NXR = NXRAN(2)          DO 231 J = 1, NXR  231     XRAN(J) = XRAN2I(J)        ENDIF        IF (NPFR .EQ. 1) BE = 0.5*AL        IF (NPFR .EQ. 2) BE = 0.0        IF (NPFR .EQ. 3) BE = AL      ELSE        IF (NPFR .EQ. 1) BE = 0.5*AL        IF (NPFR .EQ. 2) BE = AL        IF (NPFR .EQ. 3) BE = 0.0      ENDIFCC     HORIZONTAL AND VERTICAL GAPC      APB(1) = APBI(1)      IAPB = IPTOJ(2)      IF (IAPB .EQ. 0) THEN        APB(2) = APBI(2)      ELSE        IADR = I + IAPB        APB(2) = DATAR(IADR)      ENDIF      IF (PRAN2(2) .NE. 0.0)     1    APB(2) = APB(2) + PRAN2(2)*XRAN(2)      APB(2) = APB(2)*UNITI(3)CC     FRINGE FIELD INTEGRALSC      LAYK = LAYKIC      ILAYL = IPTOJ(3)      IF (ILAYL .EQ. 0) LAYL = LAYLI      IF (ILAYL .NE. 0) THEN        IADR = I + ILAYL        LAYL = DATAR(IADR)      ENDIF      IF (PRAN2(3) .NE. 0.0)     1    LAYL = LAYL + PRAN2(3)*XRAN(3)C      LAYX = LAYXICC     POLE FACE SURFACE CURVATUREC      IRAB = IPTOJ(4)      IF (IRAB .NE. 0) THEN        IADR = I + IRAB        RABT = DATAR(IADR)      ELSE        IF (BEFORE) THEN          RABT = RAB1I        ELSE          RABT = RAB2I        ENDIF      ENDIF      IF (PRAN2(4) .NE. 0.0)     1    RABT = RABT + PRAN2(4)*XRAN(4)      RABT = RABT/UNITI(8)  240 RETURN      END